(()=>{
 const hero=document.getElementById('hero'),wrap=hero?.querySelector('.model-wrap');
 if(!hero||!wrap)return;
 const bg=document.createElement('div');bg.className='dz-female-bg';hero.insertBefore(bg,hero.querySelector('.wash'));
 const girl=document.createElement('img');girl.className='model dz-female-model';girl.alt='Người mẫu nữ thời trang Hàn Quốc';girl.src='data:image/webp;base64,';wrap.appendChild(girl);
})();
